from pathlib import Path
p = Path('/home/ubuntu/lumin-candles-store/client/src/pages/Home.tsx')
s = p.read_text()
marker = '      {requestOpen && <div className="modal-backdrop"'
tracking = '''      {trackingOpen && <div className="tracking-backdrop" onClick={() => setTrackingOpen(false)}><div className="tracking-panel" onClick={(event) => event.stopPropagation()}><div className="tracking-head"><div><span className="section-label">طلب نشط · NJ-2048</span><h2>مقدم الخدمة في الطريق</h2><p>شركة درب الإنقاذ · سطحة هيدروليك</p></div><button onClick={() => setTrackingOpen(false)} className="modal-close" aria-label="إغلاق"><X size={18} /></button></div><div className="tracking-map"><div className="track-road track-road-one" /><div className="track-road track-road-two" /><div className="track-road track-road-three" /><div className="track-block track-block-one" /><div className="track-block track-block-two" /><div className="track-block track-block-three" /><div className="track-route" style={{ "--route-progress": `${trackingProgress}%` } as CSSProperties} /><div className="tracking-you"><span>موقعك</span><i /></div><div className="tracking-provider" style={{ right: `${20 + trackingProgress * .42}%`, top: `${67 - trackingProgress * .34}%` }}><span className="vehicle-pulse" /><Truck size={16} /></div><div className="track-destination"><MapPin size={17} /></div><div className="tracking-map-label">الرياض · طريق الملك فهد</div></div><div className="tracking-status"><div className="status-icon"><Truck size={19} /></div><div className="status-copy"><strong>{trackingProgress >= 100 ? "وصل مقدم الخدمة" : "في الطريق إليك"}</strong><span>{trackingProgress >= 100 ? "يرجى تأكيد بدء الخدمة" : "آخر تحديث منذ لحظات · يتتبع موقعه مباشرة"}</span></div><div className="eta-block"><strong>{trackingProgress >= 100 ? "الآن" : "٨ دقائق"}</strong><span>وقت الوصول</span></div></div><div className="tracking-progress"><div><span>انطلق مقدم الخدمة</span><span>{trackingProgress}%</span></div><div className="progress-track"><span style={{ width: `${trackingProgress}%` }} /></div></div><div className="tracking-actions"><button onClick={() => toast("تم فتح محادثة تجريبية مع مقدم الخدمة") }><MessageCircle size={16} /> مراسلة</button><button onClick={() => toast("اتصال تجريبي — سيتم تفعيله عند الإطلاق") }><Headphones size={16} /> دعم نجدة</button><button className="cancel-track" onClick={() => { setTrackingOpen(false); toast("يمكن إلغاء الطلب من الدعم قبل وصول مقدم الخدمة"); }}>خيارات الطلب</button></div><p className="tracking-note"><ShieldCheck size={13} /> التتبع تجريبي في المعاينة ولا يشارك موقعًا حقيقيًا.</p></div></div>}
'''
if marker not in s: raise SystemExit('tracking insertion marker not found')
s = s.replace(marker, tracking + marker, 1)
p.write_text(s)
css = Path('/home/ubuntu/lumin-candles-store/client/src/index.css')
s = css.read_text()
s += '''\n.tracking-backdrop { position: fixed; inset: 0; z-index: 75; display: flex; align-items: center; justify-content: center; background: rgba(7,20,14,.57); padding: 20px; backdrop-filter: blur(5px); animation: fadeIn .18s ease-out; }\n.tracking-panel { width: min(100%, 570px); overflow: hidden; border-radius: 20px; background: #f8fbf8; box-shadow: 0 25px 70px rgba(4,18,10,.3); animation: modalIn .22s ease-out; }\n.tracking-head { display: flex; align-items: flex-start; justify-content: space-between; padding: 25px 26px 17px; }\n.tracking-head h2 { margin-top: 6px; color: var(--navy); font-size: 22px; }\n.tracking-head p { margin-top: 5px; color: #809188; font-size: 10px; }\n.tracking-map { position: relative; height: 265px; overflow: hidden; background: #d7e3d7; background-image: linear-gradient(145deg, transparent 0 48%, rgba(255,255,255,.76) 48.5% 49.5%, transparent 50%), linear-gradient(28deg, transparent 0 42%, rgba(255,255,255,.82) 42.5% 43.5%, transparent 44%), repeating-linear-gradient(73deg, transparent 0 48px, rgba(161,187,164,.32) 49px 51px); }\n.tracking-map::before { position: absolute; inset: 35px -40px; border: 2px solid rgba(145,176,149,.35); border-radius: 48%; transform: rotate(19deg); content: ''; }\n.track-road { position: absolute; height: 3px; background: rgba(255,255,255,.9); box-shadow: 0 0 0 2px rgba(167,191,170,.3); }.track-road-one { width: 115%; right: -8%; top: 53%; transform: rotate(-18deg); }.track-road-two { width: 90%; left: -10%; top: 72%; transform: rotate(29deg); }.track-road-three { width: 70%; left: 11%; top: 18%; transform: rotate(76deg); }.track-block { position: absolute; border: 1px solid rgba(143,174,148,.28); background: rgba(182,207,183,.27); transform: rotate(25deg); }.track-block-one { height: 58px; width: 130px; right: 30px; top: 20px; }.track-block-two { height: 80px; width: 155px; left: 35px; bottom: 15px; }.track-block-three { height: 55px; width: 100px; left: 45%; top: 44%; }.track-route { position: absolute; right: 25%; top: 58%; width: 45%; height: 4px; border-radius: 4px; background: linear-gradient(90deg, #759b5c 0 var(--route-progress), rgba(117,155,92,.2) var(--route-progress) 100%); box-shadow: 0 0 0 2px rgba(255,255,255,.35); transform: rotate(-22deg); transform-origin: right center; transition: width 1s ease; }.tracking-you, .tracking-provider, .track-destination { position: absolute; display: flex; align-items: center; justify-content: center; }.tracking-you { top: 56%; right: 19%; flex-direction: column; gap: 2px; color: #4f7356; font-size: 9px; font-weight: 700; }.tracking-you i { height: 15px; width: 15px; border: 3px solid white; border-radius: 999px; background: #80b45f; box-shadow: 0 3px 9px rgba(40,82,44,.28); }.tracking-provider { height: 34px; width: 34px; border: 2px solid white; border-radius: 999px 999px 999px 4px; background: var(--navy); color: var(--lime); box-shadow: 0 4px 10px rgba(40,75,44,.25); transform: rotate(-45deg); transition: right 1.4s ease, top 1.4s ease; }.tracking-provider svg { transform: rotate(45deg); }.vehicle-pulse { position: absolute; height: 8px; width: 8px; border-radius: 999px; background: #d4f250; box-shadow: 0 0 0 6px rgba(212,242,80,.22); }.track-destination { top: 22%; left: 18%; height: 30px; width: 30px; border-radius: 999px 999px 999px 5px; background: #77965d; color: white; transform: rotate(-45deg); }.track-destination svg { transform: rotate(45deg); }.tracking-map-label { position: absolute; bottom: 12px; right: 15px; border-radius: 6px; background: rgba(248,252,248,.85); padding: 5px 8px; color: #68806c; font-size: 9px; backdrop-filter: blur(5px); }\n.tracking-status { display: flex; align-items: center; gap: 11px; padding: 19px 25px 14px; }.status-icon { display: flex; height: 43px; width: 43px; align-items: center; justify-content: center; border-radius: 12px; background: #e3f3bc; color: #4d7b3a; }.status-copy { flex: 1; }.status-copy strong, .status-copy span, .eta-block strong, .eta-block span { display: block; }.status-copy strong { color: #2e4939; font-size: 13px; }.status-copy span { margin-top: 4px; color: #87978e; font-size: 9px; }.eta-block { text-align: left; }.eta-block strong { color: #4e7c48; font-family: 'Manrope', sans-serif; font-size: 18px; }.eta-block span { color: #8c9d92; font-size: 9px; }.tracking-progress { padding: 0 25px 17px; }.tracking-progress > div:first-child { display: flex; justify-content: space-between; color: #7f9186; font-size: 9px; }.tracking-progress > div:first-child span:last-child { color: #5c8b4d; font-weight: 700; }.progress-track { height: 5px; margin-top: 8px; overflow: hidden; border-radius: 999px; background: #e1eae0; }.progress-track span { display: block; height: 100%; border-radius: inherit; background: var(--lime); transition: width 1s ease; }.tracking-actions { display: flex; gap: 7px; border-top: 1px solid #e1eae2; padding: 15px 25px; }.tracking-actions button { display: inline-flex; align-items: center; gap: 6px; border: 1px solid #d7e3d8; border-radius: 999px; padding: 9px 12px; color: #50715d; font-size: 10px; }.tracking-actions button:hover { border-color: #a9c98c; background: #eff8e6; }.tracking-actions .cancel-track { margin-right: auto; border-color: transparent; color: #8e9e95; }.tracking-note { display: flex; align-items: center; justify-content: center; gap: 5px; padding: 0 20px 18px; color: #9aa9a0; font-size: 9px; }.tracking-note svg { color: #83a466; }\n@media (max-width: 640px) { .tracking-backdrop { align-items: end; padding: 0; }.tracking-panel { border-radius: 20px 20px 0 0; }.tracking-head { padding: 22px 20px 15px; }.tracking-map { height: 235px; }.tracking-status, .tracking-progress { padding-inline: 20px; }.tracking-actions { padding-inline: 20px; }.tracking-actions button { padding: 8px 9px; font-size: 9px; } }\n'''
css.write_text(s)
